# Lesson 1, part 3 (who reads the statements and what each reader asks) and part 4 (who requires reporting: law, standards, regulator, audit).
# Israeli facts: corporate tax 23% (since 2018); Companies Law 1999; Securities Law 1968 and the 1970 periodic and immediate reports regulations
# (annual report within three months, quarterly within two months); Israeli Accounting Standard No. 29 (IFRS for public companies from 1.1.2008).

# ================================================================ part 4
opener(4, 'מי משתמש בדוחות, ולמה', 'שאלת החלק: בשביל מי נבנים הדוחות, ומה כל קורא מחפש בהם?',
       ['מטרת הדוחות: משקיעים ונושים, ומעגל שני', 'כל קורא, ואיזו שורה בדוחות מעניינת אותו', 'מה הופך את המספרים בדוח לשימושיים', 'למה לא מספיק לסמוך על המנהל', 'שאלות אמריקאיות לאורך הדרך'], 25)

S('s-goal', 'מטרת הדיווח', 'בשביל מה כל הדוחות האלה?',
  DEF('מטרת הדוחות הכספיים (Objective of financial reporting)', 'לספק מידע כספי שימושי הקשור בראש ובראשונה להקצאת משאבים לישות המדווחת: למשקיעים ולנושים. רק במעגל השני, ובאופן עקיף, יש לדוחות חשיבות לבעלי עניין נוספים.', 'יוסי שוקל לקנות 20% מקפה נועה, והבנק שוקל לתת לה הלוואה: שניהם במעגל הראשון. העובדים ורשות המסים קוראים את הדוח, אבל הוא לא נבנה בשבילם.', n=1, trm='objective')
  + DEF('המסגרת המושגית (Conceptual Framework)', 'מסמך היסוד של התקינה הבינלאומית. הוא קובע למה מדווחים, למי, ומה הופך מידע לטוב.', 'כשאין כלל ברור לעסקה חדשה, החברה בוחרת טיפול שמתאים למסגרת.', n=2, trm='cfw')
  + BAND('dg', 'שימו לב לפועל: האנשים מחליטים. המידע רק עוזר להם להחליט טוב יותר.', 3)
  + TOON('investor', 'אני לא קונה בית קפה. אני קונה את הרווחים העתידיים שלו.', 4), kick='חלק 4 · הגדרה והדגמה')

U = [('משקיעים', 'כמה ירוויחו על הכסף?', 'investor', 1, 0), ('בנק ומלווים', 'האם יחזירו את ההלוואה?', 'bank', 1, 0), ('ספקים', 'האם ישלמו לי בזמן?', 'truck', 1, 0),
     ('רשות המסים', 'כמה מס מגיע?', 'taxman', 2, 2), ('עובדים', 'האם העבודה יציבה?', 'worker', 2, 2), ('הנהלה', 'איך לנהל טוב יותר?', 'cup', 3, 1)]
S('s-users', 'מי קורא את הדוחות', 'מי קורא את הדוחות של קפה נועה?',
  (('<div class="card hubw">' + HUB(U) + '</div>') if MODE == 'deck' else TABLE(['קורא', 'השאלה שלו'], [(a, b) for a, b, *_ in U]))
  + BAND('dg', 'בירוק: המעגל הראשון, משקיעים ונושים. באפור: המעגל השני. בכתום: ההנהלה, מבפנים.', 4), kick='חלק 4 · מפה')

_r, _n = STEPROWS([
    ('<b>משקיע</b>', 'רווח והפסד', 'הרווח הנקי: כמה נשאר לבעלים. במאזן: ההון העצמי, החלק שלהם.', 0),
    ('<b>בנק</b>', 'רווח והפסד, מאזן', 'הרווח התפעולי: יש ממה להחזיר? במאזן: כמה חוב כבר יש.', 0),
    ('<b>ספק</b>', 'מאזן', 'נכסים שוטפים מול התחייבויות שוטפות: יהיה כסף לשלם לי בחודשים הקרובים?', 0),
    ('<b>רשות המסים</b>', 'רווח והפסד', 'הרווח לפני מס: ממנו מחשבים את המס.', 0),
    ('<b>עובדים</b>', 'רווח והפסד', 'האם יש רווח: העבודה יציבה, ואולי יש בונוס.', 0)])
S('s-users-look', 'מה כל קורא מחפש', 'כל קורא מסתכל על שורה אחרת',
  '<table class="tbl2 stmt"><tr><th>הקורא</th><th>באיזה דוח</th><th>איזו שורה, ולמה</th></tr>' + _r.replace('class="amt"', 'class="rep"') + '</table>'
  + BAND('dg', 'אותם שני דוחות, וכל קורא שואל את השאלה שלו. לכן חשוב לדעת לקרוא אותם היטב.', _n), kick='חלק 4 · שורה אחר שורה')

MCS('m-users', 'בדיקה: מי מחפש מה', 'בדיקה: מי מחפש מה בדוחות?', [
    mc('mu1', 'בשביל מי, בראש ובראשונה, נבנים הדוחות הכספיים?', ['משקיעים ונושים, שמעמידים לחברה כסף', 'רשות המסים', 'העובדים', 'ההנהלה של החברה'], 0, 'המטרה: מידע למי שמעמיד משאבים. האחרים במעגל השני.'),
    mc('mu3', 'משקיע רוצה לדעת כמה נשאר לבעלים מהפעילות של השנה. איזו שורה יבדוק?', ['הרווח הנקי', 'ההכנסות ממכירות', 'עלות המכירות', 'המזומן'], 0, 'הרווח הנקי הוא השורה התחתונה: מה שנשאר אחרי כל ההוצאות והמס.')])

MCS('m-users2', 'בדיקה: מי מחפש מה, המשך', 'בדיקה: מי מחפש מה בדוחות? המשך', [
    mc('mu2', 'ספק נותן לקפה נועה סחורה לתשלום בעוד 30 יום. מה הכי חשוב לו לבדוק?', ['נכסים שוטפים מול התחייבויות שוטפות, במאזן', 'הרווח הגולמי', 'הון המניות', 'הציוד והריהוט'], 0, 'הוא ייפרע בקרוב: מה שחשוב לו הוא מה שיהפוך למזומן בקרוב, מול מה שצריך לשלם בקרוב.'),
    mc('mu4', 'הבנק שוקל הלוואה לחמש שנים. מה מבין אלה מעניין אותו פחות מכל?', ['כמה כיסאות יש בבית הקפה', 'הרווח התפעולי', 'החובות הקיימים', 'ההון העצמי'], 0, 'מספר הכיסאות לא אומר דבר על היכולת להחזיר. השאר כן.')])

S('s-qual1', 'שני מאפיינים יסודיים', 'מה הופך מידע לשימושי? שני תנאי יסוד',
  '<div class="row eq2 top">'
  + DEF('רלוונטיות (Relevance)', 'מידע שיכול לשנות החלטה. למשל, הוא עוזר לנחש מה יקרה בשנה הבאה.', 'הרווח החודשי של קפה נועה עוזר ליוסי לחזות את הרווח של השנה הבאה. צבע הקירות לא.', n=1, trm='relev')
  + DEF('ייצוג נאמן (Faithful representation)', 'המספר מתאר את מה שבאמת קרה: לא חסר בו דבר, הוא לא מוטה לטובת אף אחד, ואין בו טעויות.', 'חשבון חשמל של דצמבר נרשם בדצמבר, גם אם הוא מקטין את הרווח של החודש.', n=2, trm='faith') + '</div>'
  + BAND('dg', 'צריך את שניהם יחד. מספר מדויק שלא נוגע להחלטה לא עוזר, ומספר רלוונטי שאי אפשר לסמוך עליו מזיק.', 3)
  + MEME('הדוח של יוסי', [('report', 'רלוונטי: רווח, מכירות, חובות'), ('mask', 'לא נאמן: ״שכחנו״ את החשמל')], 4, 'sm side'), kick='חלק 4 · הגדרה והדגמה')

S('s-qual2', 'ארבעה מאפיינים משפרים', 'ועוד ארבעה מאפיינים שמשפרים את המידע',
  '<div class="row eq2 top"><div class="col">'
  + DEF('השוואתיות (Comparability)', 'אפשר להשוות בין חברות ובין שנים, כי כולן מודדות באותה דרך.', 'שני בתי קפה רושמים שכר של בעלים באותו אופן.', n=1, trm='compar')
  + DEF('ניתנות לאימות (Verifiability)', 'בודק עצמאי יגיע לאותו מספר.', 'רואה החשבון סופר את שקי הפולים ומשווה לחשבונית.', n=2, trm='verif') + '</div><div class="col">'
  + DEF('עדכניות (Timeliness)', 'המידע מגיע בזמן, לפני שההחלטה כבר התקבלה.', 'דוח של ינואר שמגיע בפברואר עוזר לבנק. בדצמבר הוא כבר מאוחר.', n=3, trm='timely')
  + DEF('מובנות (Understandability)', 'המידע מסודר ומוצג בבהירות, לקורא עם ידע סביר.', '״הכנסות: 42,000״, ולא 3,000 קבלות.', n=4, trm='underst') + '</div></div>', kick='חלק 4 · הגדרה והדגמה')

MCS('m-qual', 'בדיקה: איזה מאפיין נפגע', 'בדיקה: איזה מאפיין של המידע נפגע?', [
    mc('mq1', 'המנהל לא רשם חשבון חשמל של דצמבר, כדי שהרווח ייראה גבוה יותר. מה נפגע?', ['ייצוג נאמן', 'עדכניות', 'מובנות', 'אף מאפיין'], 0, 'חסרה הוצאה, והדוח מוטה לטובת המנהל: הוא לא מתאר את מה שקרה.'),
    mc('mq2', 'הדוח השנתי של 2025 התפרסם רק בדצמבר 2026. מה נפגע?', ['עדכניות', 'ייצוג נאמן', 'השוואתיות', 'ניתנות לאימות'], 0, 'המספרים אולי נכונים, אבל הגיעו מאוחר מדי להחלטות.'),
])

MCS('m-qual2', 'בדיקה: איזה מאפיין נפגע, המשך', 'בדיקה: איזה מאפיין נפגע? המשך', [
    mc('mq3', 'שני בתי קפה מודדים רווח בשתי דרכים שונות. מה נפגע?', ['השוואתיות', 'עדכניות', 'מובנות', 'רלוונטיות'], 0, 'אי אפשר להשוות ביניהם: אותו מספר מייצג דברים שונים.'),
    mc('mq4', 'בדוח לבנק מפורטים צבע הלוגו ומספר הכיסאות, ולא החובות. מה נפגע?', ['רלוונטיות', 'ייצוג נאמן', 'עדכניות', 'ניתנות לאימות'], 0, 'המידע שבדוח לא יכול לשנות את החלטת ההלוואה.')])

S('s-asym', 'פערי מידע ובעיית הנציג', 'למה לא לסמוך פשוט על המנהל?',
  '<div class="row eq2 top">'
  + DEF('פערי מידע (Information asymmetry)', 'צד אחד יודע יותר מהצד השני. ההנהלה יודעת על העסק הרבה יותר מהקוראים בחוץ.', 'נועה יודעת שמכונת האספרסו עומדת להתקלקל. יוסי, המשקיע, לא יודע.', n=1, trm='asym')
  + DEF('בעיית הנציג (Agency problem)', 'המנהל אמור לעבוד בשביל הבעלים, אבל לפעמים דואג קודם לעצמו, והבעלים לא רואים כל מה שהוא עושה.', 'מנהל שמקבל בונוס לפי הרווח מעדיף שהרווח ייראה גבוה, גם כשהוא לא.', n=2, trm='agency') + '</div>'
  + BAND('dg', 'מכאן הצורך בשלושה דברים: כללים אחידים שקובעים איך מודדים, חובה לפרסם, ובודק חיצוני. זה חלק 4.', 3)
  + MEME('שני דוחות, אותו בית קפה', [('happy', 'הדוח שהמנהל היה רוצה לפרסם'), ('mag', 'הדוח שהמשקיע צריך לקבל')], 4, 'sm side'), kick='חלק 4 · הגדרה והדגמה')

opener(5, 'מי מחייב לדווח', 'שאלת החלק: מי קובע שחברה חייבת לפרסם דוחות, ולפי אילו כללים?',
       ['חברה פרטית וחברה ציבורית', 'כללי חשבונאות מקובלים, ומי כותב אותם', 'החוקים בישראל, ורשות ניירות ערך', 'מה מפרסמים, ומתי', 'ביקורת ורואה חשבון מבקר'], 20)

S('s-pubpriv', 'פרטית או ציבורית', 'קודם כול: חברה פרטית או חברה ציבורית?',
  '<div class="row eq2 top">'
  + DEF('חברה פרטית (Private company)', 'כמו ארוחת שישי משפחתית: כל הבעלים יושבים סביב אותו שולחן ומכירים זה את זה. המניות לא נמכרות לציבור.', 'קפה נועה בע״מ: נועה, ואולי בקרוב יוסי. הדוחות הולכים לבעלים, לבנק ולרשות המסים.', n=1, trm='priv')
  + DEF('חברה ציבורית (Public company)', 'כמו מסעדה עם חלון ראווה לרחוב: כל אחד יכול להיכנס ולקנות מניה בבורסה. ומי שמזמין את כל הרחוב להשקיע, חייב להראות לכולם את המספרים.', 'רשת מזון שמניותיה נסחרות בבורסה בתל אביב: הדוחות שלה פתוחים לכולם באינטרנט.', n=2, trm='pub') + '</div>'
  + BAND('dg', 'שתיהן חייבות דוח שנתי מבוקר. ההבדל: הציבורית מפרסמת אותו לכולם, ובתדירות גבוהה יותר.', 3)
  + MEME('שני סוגי חברות', [('cup', 'פרטית: הדוח נשאר במשפחה'), ('report', 'ציבורית: הדוח בחלון הראווה')], 4, 'sm side'), kick='חלק 5 · הגדרה והדגמה')

S('s-gaap', 'כללים משותפים', 'שפה צריכה דקדוק: כללים משותפים',
  '<div class="card qstem"><p>' + TX('נניח שכל חברה הייתה מודדת רווח בדרך שלה: אחת רושמת שכר לבעלים כהוצאה, ואחרת לא. אי אפשר היה להשוות ביניהן.') + '</p></div>'
  + '<div class="row eq2 top">'
  + DEF('כללי חשבונאות מקובלים (GAAP)', 'באנגלית Generally Accepted Accounting Principles: כל הכללים שלפיהם מכינים דוחות כספיים במדינה מסוימת.', 'בארצות הברית US GAAP. בישראל: תקינה ישראלית לחברות פרטיות, ותקינה בינלאומית לחברות ציבוריות.', n=1, trm='gaap')
  + DEF('תקן חשבונאות (Accounting standard)', 'כלל כתוב שאומר איך לטפל בסוג מסוים של עסקה.', 'תקן הכנסות קובע שהמינוי של חדר הכושר נרשם כהכנסה לאורך 12 חודשים.', n=2, trm='std') + '</div>'
  + TOON('gavel', 'בלי כללים משותפים, כל חברה ממציאה את הרווח שלה.', 3), kick='חלק 5 · הגדרה והדגמה')

S('s-ifrs', 'מי כותב את הכללים', 'מי כותב את הכללים?',
  '<div class="row eq2 top"><div class="col">'
  + DEF('המוסד הבינלאומי לתקינה בחשבונאות (IASB)', 'באנגלית International Accounting Standards Board. גוף עצמאי בלונדון שכותב את כללי הדיווח הבינלאומיים ואת המסגרת המושגית.', 'הוא פרסם את התקן שקובע איך חברה רושמת חוזה שכירות ארוך.', n=1, trm='iasb')
  + DEF('תקני דיווח כספי בינלאומיים (IFRS)', 'באנגלית International Financial Reporting Standards: הכללים שה-IASB כותב. יותר מ-140 מדינות ותחומי שיפוט מחייבים אותם.', 'חברה ישראלית וחברה גרמנית מדווחות לפי IFRS, ולכן אפשר להשוות ביניהן.', n=2, trm='ifrs') + '</div><div class="col">'
  + DEF('הוועדה האמריקאית לתקינה בחשבונאות (FASB)', 'באנגלית Financial Accounting Standards Board: הגוף שכותב את US GAAP, כללי החשבונאות בארצות הברית.', 'חברה אמריקאית שנסחרת בניו יורק מדווחת לפי US GAAP.', n=3, trm='fasb')
  + DEF('המוסד הישראלי לתקינה בחשבונאות', 'באנגלית Israel Accounting Standards Board. כותב את התקנים הישראליים. תקן מספר 29 שלו חייב חברות ציבוריות לעבור ל-IFRS מ-1.1.2008.', 'קפה נועה, חברה פרטית, רשאית לדווח לפי התקינה הישראלית.', n=4, trm='isasb') + '</div></div>', kick='חלק 5 · הגדרה והדגמה')

S('s-lawdefs', 'שני חוקים', 'שני חוקים שמחייבים לדווח',
  '<div class="row eq2 top">'
  + DEF('חוק החברות (Companies Law)', 'החוק שקובע איך חברה בישראל מתנהלת, כולל חובת דוחות שנתיים וביקורת.', 'גם קפה נועה בע״מ, חברה פרטית, חייבת דוח שנתי מבוקר.', n=1, trm='complaw')
  + DEF('חוק ניירות ערך (Securities Law)', 'החוק שמחייב חברות שגייסו כסף מהציבור לפרסם דוחות לכולם.', 'חברה שמניותיה נסחרות בבורסה בתל אביב מפרסמת דוח כל רבעון.', n=2, trm='seclaw') + '</div>'
  + BAND('dg', 'החוק אומר <b>שחייבים</b> לדווח. התקנים אומרים <b>איך</b> מודדים. הרגולטור <b>בודק</b> שזה נעשה.', 3)
  + TOON('gavel', 'החוק לא מסביר איך מודדים רווח. בשביל זה יש תקנים.', 4), kick='חלק 5 · הגדרה והדגמה')

S('s-laws', 'החוקים בישראל', 'ומי מחייב? הסולם, מהחוק ועד הדוח',
  (('<div class="card hubw">' + LADDER([('חוק החברות, התשנ״ט-1999', 'כל חברה: פנקסים, דוחות כספיים שנתיים ורואה חשבון מבקר', 1),
                                        ('חוק ניירות ערך, התשכ״ח-1968, ותקנות הדיווח מ-1970', 'תאגיד מדווח: דוח שנתי, דוחות רבעוניים ודיווחים מיידיים', 2),
                                        ('רשות ניירות ערך', 'הרגולטור: בודק את הדיווחים ואוכף את החוק', 3),
                                        ('תקני חשבונאות', 'איך מודדים: IFRS לחברות ציבוריות, תקינה ישראלית לפרטיות', 4),
                                        ('חוק רואי חשבון ופקודת מס הכנסה', 'מי רשאי לבקר, ואיזה דוח מגישים למס', 5)]) + '</div>') if MODE == 'deck' else
   TABLE(['מקור', 'מה הוא קובע'], [['חוק החברות, התשנ״ט-1999', 'כל חברה: פנקסים, דוחות כספיים שנתיים ורואה חשבון מבקר'], ['חוק ניירות ערך, התשכ״ח-1968, ותקנות הדיווח מ-1970', 'תאגיד מדווח: דוח שנתי, דוחות רבעוניים ודיווחים מיידיים'],
                                    ['רשות ניירות ערך', 'הרגולטור: בודק את הדיווחים ואוכף את החוק'], ['תקני חשבונאות', 'איך מודדים: IFRS לחברות ציבוריות, תקינה ישראלית לפרטיות'], ['חוק רואי חשבון ופקודת מס הכנסה', 'מי רשאי לבקר, ואיזה דוח מגישים למס']]))
  , kick='חלק 5 · מפה')

S('s-maya', 'תאגיד מדווח ומאי״ה', 'חברה ציבורית: מה מפרסמים, ומתי',
  '<div class="row eq2 top"><div class="col">'
  + DEF('תאגיד מדווח (Reporting entity)', 'חברה שגייסה כסף מהציבור, בדרך כלל כי המניות או אגרות החוב שלה נסחרות בבורסה, ולכן חייבת לדווח לציבור.', 'חברת מזון שמניותיה נסחרות בבורסה בתל אביב. קפה נועה בע״מ אינה תאגיד מדווח.', n=1, trm='repco')
  + DEF('רשות ניירות ערך (Israel Securities Authority)', 'הרגולטור שמגן על המשקיעים: בודק דיווחים ואוכף את החוק.', 'הרשות מטילה עיצום כספי על חברה שאיחרה בפרסום דוח.', n=2, trm='isa')
  + '</div><div class="col">' + DEF('מאי״ה (Maya)', 'האתר של הבורסה בתל אביב שבו כל אחד קורא את הדיווחים של החברות: maya.tase.co.il.', 'במפגש 2 נקרא שם דוחות של חברה אמיתית.', n=3, trm='maya')
  + BAND('note', 'החברות מגישות את הדיווחים לרשות במערכת שלה, והציבור קורא אותם במאי״ה.', 4) + '</div></div>', kick='חלק 5 · הגדרה והדגמה')

S('s-reports', 'מה מפרסמים ומתי', 'שלושה סוגי דיווח, ושלושה מועדים',
  '<div class="row eq3 top">'
  + DEF('דוח תקופתי (Annual report)', 'הדוח השנתי, עם דוחות כספיים מבוקרים, בתוך שלושה חודשים מסוף השנה.', 'שנה שמסתיימת ב-31.12.2026: הדוח מתפרסם עד 31.3.2027.', n=1, trm='annual')
  + DEF('דוח רבעוני (Quarterly report)', 'עדכון לכל אחד משלושת הרבעונים הראשונים, בתוך חודשיים מסוף הרבעון.', 'רבעון שמסתיים ב-31.3: עד 31.5.', n=2, trm='quarter')
  + DEF('דיווח מיידי (Immediate report)', 'הודעה לציבור כשקורה אירוע מהותי, בלי לחכות לדוח הבא.', 'החברה זכתה במכרז גדול, או שהמנהל הכללי התפטר.', n=3, trm='immed') + '</div>'
  + BAND('dg', 'זו [[timely|עדכניות]] בפועל: החוק קובע מועדים, כדי שהמידע יגיע לפני ההחלטות.', 4)
  + TOON('clock', 'רבעון 4 לא מקבל דוח משלו. הוא מסתתר בתוך הדוח השנתי.', 5), kick='חלק 5 · הגדרה והדגמה')

S('s-audit', 'ביקורת', 'מי בודק את הדוחות?',
  '<div class="row eq3 top">'
  + DEF('ביקורת (Audit)', 'בדיקה חיצונית של הדוחות, כדי שאפשר יהיה לסמוך עליהם. היא נותנת ביטחון סביר, לא ערובה.', 'סופרים מלאי, מקבלים אישור יתרה מהבנק, ובודקים מדגם של חשבוניות.', n=1, trm='audit')
  + DEF('רואה חשבון מבקר (Auditor)', 'רואה חשבון בעל רישיון, שאינו עובד בחברה ואינו תלוי בה, ושבודק את הדוחות.', 'משרד רואי חשבון חיצוני שבודק את קפה נועה פעם בשנה.', n=2, trm='auditor')
  + DEF('חוות דעת (Audit opinion)', 'המסקנה הכתובה של המבקר. ״נקייה״: הדוחות משקפים באופן נאות, מכל הבחינות המהותיות.', 'הסתייגות או אזהרה בחוות הדעת היא סימן לקורא לבדוק לעומק.', n=3, trm='opinion') + '</div>'
  + BAND('dg', 'הביקורת מחזקת שני מאפיינים שלמדנו: [[verif|ניתנות לאימות]] ו[[faith|ייצוג נאמן]]. היא עונה על [[asym|פערי המידע]] מחלק 3.', 4)
  + TOON('mag', 'אני לא בודק כל קבלה. אני בודק מספיק כדי לחתום.', 5), kick='חלק 5 · הגדרה והדגמה')
